import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { primitives } from '@/primitives';
import { text } from '@/text';

export default function createNode(config, ctx) {
  // Root object
  const root = new Group();
  root.name = config.name || 'PricingCard3';

  // Plane geometry – size based on image aspect (512:320 ≈ 1.6:1)
  const planeWidth = 1.6;
  const planeHeight = 1.0;
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial();
  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load texture asynchronously, keep reference for cleanup
  let texture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      texture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Create text objects from config
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textObjects = [];
  for (const item of textItems) {
    const opts = {
      fontSize: item.typography?.fontSize ?? 39,
      color: (config.intent?.visualSpec?.colors?.paper) ?? '#e8ecf2',
      align: 'center',
    };
    const txt = ctx.fontAtlas.createText(item.text, opts);
    // Position text slightly in front of the plane
    txt.position.set(0, 0, 0.01);
    root.add(txt);
    textObjects.push(txt);
  }

  // No cinematic primitives for this node, but keep placeholder for future
  const primitiveHandles = [];

  // Handlers container (none defined)
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose primitives if any (none here)
    for (const ph of primitiveHandles) {
      if (ph && typeof ph.cleanup === 'function') ph.cleanup();
    }

    // Dispose texture
    if (texture) {
      texture.dispose();
      texture = null;
    }

    // Dispose material & geometry
    material.dispose();
    geometry.dispose();

    // Remove and dispose text objects
    for (const txt of textObjects) {
      if (txt.parent) txt.parent.remove(txt);
    }
    textObjects.length = 0;

    // Kill any GSAP timelines (none used here)
    gsap.globalTimeline.clear();

    // Clear handlers
    root.userData.handlers = {};
  };

  return root;
}
